// NovaFirmware.swift — Firmware loading: built-in default + custom via Files app.

import Foundation

/// NOVA firmware: runs at machine privilege before the user program.
/// Handles memory init, stack setup, trap vectors, and console I/O.
struct NovaFirmware {

    /// Default firmware: NovaShell (interactive shell).
    /// Runs at 0x0. Programs load at 0x1000 on top of it (via the app's
    /// program loader or NovaShell's `run <file>` command).
    ///
    /// The firmware lives as a FILE (not just embedded bytes): on launch the
    /// app materializes the built-in image to `NOVA/firmware/novash.bin`, and
    /// Run loads that file into guest memory. This is the demand-load
    /// structure: firmware (and later, modules) come from storage, keeping
    /// the app's resident memory low. Embedded bytes are the fallback.
    static var defaultFirmwareURL: URL {
        NovaFolders.firmwareDir.appendingPathComponent("novash.bin")
    }

    /// Materialize the built-in firmware to its file. Content-aware: rewrites
    /// the file whenever the embedded bytes differ from what's on disk. This
    /// ensures firmware updates always reach the device, even though the
    /// marketing version never changes. A user-replaced custom firmware file
    /// is preserved only if the Firmware tab has it selected (not the default).
    static func refreshBuiltIn() {
        let fm = FileManager.default
        let url = defaultFirmwareURL
        let embedded = Data(novaShellBytes)
        guard !embedded.isEmpty else { return }
        try? fm.createDirectory(at: NovaFolders.firmwareDir, withIntermediateDirectories: true)
        let onDisk = try? Data(contentsOf: url)
        if onDisk != embedded {
            try? embedded.write(to: url, options: .atomic)
        }
    }

    static var defaultImage: Data {
        let embedded = Data(novaShellBytes)
        // Prefer the firmware FILE (demand-loaded from storage), but verify
        // it matches the embedded bytes. If corrupt/missing, use embedded.
        if let data = try? Data(contentsOf: defaultFirmwareURL),
           !data.isEmpty, data == embedded {
            return data
        }
        // ...fall back to embedded bytes...
        if !embedded.isEmpty {
            return embedded
        }
        // ...then to a minimal JMP32 stub to 0x1000 (program entry).
        var bytes = [UInt8]()
        bytes.append(0xA1) // JMP32
        let off = Int32(0x1000 - 5)
        let u = UInt32(bitPattern: off)
        for i in 0..<4 { bytes.append(UInt8((u >> (i*8)) & 0xFF)) }
        return Data(bytes)
    }

    /// Load custom firmware from a file URL (via Files app document picker).
    static func loadCustom(from url: URL) throws -> Data {
        // Security-scoped access for Files app URLs
        guard url.startAccessingSecurityScopedResource() else {
            throw NovaError.firmwareAccessDenied
        }
        defer { url.stopAccessingSecurityScopedResource() }
        let data = try Data(contentsOf: url)
        guard data.count <= 1024 * 1024 else { throw NovaError.firmwareTooLarge }
        return data
    }
}

enum NovaError: Error, LocalizedError {
    case firmwareAccessDenied
    case firmwareTooLarge
    case programTooLarge
    case noProgramLoaded

    var errorDescription: String? {
        switch self {
        case .firmwareAccessDenied: return "Could not access the firmware file."
        case .firmwareTooLarge: return "Firmware image exceeds 1MB."
        case .programTooLarge: return "Program exceeds available guest memory."
        case .noProgramLoaded: return "Load a program first."
        }
    }
}

